scene.background = new THREE.Color(0x000000);

const sun = new THREE.Mesh(
    new THREE.CircleGeometry(14, 64),
    new THREE.MeshBasicMaterial({ color: 0xff0000 })
);
sun.position.set(0, 2, -20);
scene.add(sun);

const slashes = [];
const slashGroup = new THREE.Group();
for(let i = 0; i < 2; i++) {
    const mesh = new THREE.Mesh(
        new THREE.PlaneGeometry(30, 0.2 - i * 0.05),
        new THREE.MeshBasicMaterial({ color: 0x000000 })
    );
    mesh.position.set(0, 6 - i * 1.5, -19 + i);
    slashes.push({ mesh, speed: 1.5 + i * 0.5, phase: i * Math.PI });
    slashGroup.add(mesh);
}
scene.add(slashGroup);

const peak = new THREE.Mesh(
    new THREE.ConeGeometry(3, 8, 4),
    new THREE.MeshBasicMaterial({ color: 0x000000 })
);
peak.position.set(0, -6, -8);
peak.rotation.z = Math.PI;
peak.scale.set(1.2, 1, 0.3);
scene.add(peak);

const samurai = new THREE.Group();
const black = new THREE.MeshBasicMaterial({ color: 0x000000 });

const body = new THREE.Mesh(new THREE.CylinderGeometry(0.4, 0.5, 2, 7), black);
body.position.y = 1;
samurai.add(body);

const head = new THREE.Mesh(new THREE.SphereGeometry(0.32, 8, 8), black);
head.position.y = 2.3;
samurai.add(head);

const hair = new THREE.Group();
for(let i = 0; i < 6; i++) {
    const spike = new THREE.Mesh(new THREE.ConeGeometry(0.07, 0.35, 3), black);
    spike.position.set(
        Math.sin(i) * 0.15,
        2.55 + Math.random() * 0.1,
        Math.cos(i) * 0.1
    );
    spike.rotation.z = (i - 2.5) * 0.25;
    hair.add(spike);
}
samurai.add(hair);

const sword = new THREE.Mesh(new THREE.BoxGeometry(0.1, 3, 0.05), black);
sword.position.set(-0.5, 1.2, 0.3);
sword.rotation.z = -0.1;
samurai.add(sword);

const guard = new THREE.Mesh(new THREE.CylinderGeometry(0.2, 0.2, 0.05, 6), black);
guard.rotation.x = Math.PI / 2;
guard.position.set(-0.5, -0.3, 0.3);
samurai.add(guard);

const lArm = new THREE.Mesh(new THREE.CylinderGeometry(0.12, 0.15, 1.2, 5), black);
lArm.position.set(-0.4, 1.5, 0.25);
lArm.rotation.z = -0.3;
samurai.add(lArm);

const rArm = new THREE.Mesh(new THREE.CylinderGeometry(0.12, 0.15, 1.0, 5), black);
rArm.position.set(0.35, 1.4, 0.2);
rArm.rotation.z = 0.2;
samurai.add(rArm);

const lLeg = new THREE.Mesh(new THREE.CylinderGeometry(0.18, 0.12, 1.5, 5), black);
lLeg.position.set(-0.3, -0.6, 0);
samurai.add(lLeg);

const rLeg = new THREE.Mesh(new THREE.CylinderGeometry(0.18, 0.12, 1.5, 5), black);
rLeg.position.set(0.3, -0.6, 0);
samurai.add(rLeg);

const cloth1 = new THREE.Mesh(new THREE.BoxGeometry(0.5, 1.2, 0.05), black);
cloth1.position.set(0.5, 0.3, -0.2);
cloth1.rotation.z = -0.4;
samurai.add(cloth1);

const cloth2 = new THREE.Mesh(new THREE.BoxGeometry(0.3, 0.9, 0.05), black);
cloth2.position.set(-0.55, 0.2, -0.15);
cloth2.rotation.z = 0.5;
samurai.add(cloth2);

samurai.position.set(0, -1.8, -8);
scene.add(samurai);

camera.position.set(0, 0, 10);

let t = 0;
function animate() {
