function createArrow(color, thickness = 0.03) {
  const group = new THREE.Group();
  const shaftGeo = new THREE.CylinderGeometry(thickness, thickness, 1, 16);
  const shaftMat = new THREE.MeshStandardMaterial({ color: color, roughness: 0.3, metalness: 0.1, emissive: color, emissiveIntensity: 0.1 });
  const shaft = new THREE.Mesh(shaftGeo, shaftMat);
  shaft.position.y = 0.5;
  group.add(shaft);

  const headGeo = new THREE.ConeGeometry(thickness * 2.5, thickness * 6, 16);
  const headMat = new THREE.MeshStandardMaterial({ color: color, roughness: 0.3, metalness: 0.1, emissive: color, emissiveIntensity: 0.15 });
  const arrowHead = new THREE.Mesh(headGeo, headMat);
  arrowHead.position.y = 1 + thickness * 3;
  group.add(arrowHead);

  return { group, shaft, head: arrowHead, material: shaftMat };
}

