const trailPoints = [];
const maxTrailPoints = 60;
const trailGeometry = new THREE.BufferGeometry();
const trailMaterial = new THREE.LineBasicMaterial({ color: 0xa29bfe, transparent: true, opacity: 0.4, linewidth: 2 });
const trailLine = new THREE.Line(trailGeometry, trailMaterial);
trailLine.frustumCulled = false;
scene.add(trailLine);

function createLabelSprite(text, color) {
  const canvas = document.createElement('canvas');
  const context = canvas.getContext('2d');
  canvas.width = 256;
  canvas.height = 128;
  context.fillStyle = 'rgba(255, 255, 255, 0)';
  context.fillRect(0, 0, canvas.width, canvas.height);
  context.font = 'bold 44px Inter, sans-serif';
  context.fillStyle = color;
  context.textAlign = 'center';
  context.textBaseline = 'middle';
  context.fillText(text, 128, 64);

  const texture = new THREE.CanvasTexture(canvas);
  const spriteMaterial = new THREE.SpriteMaterial({ map: texture, transparent: true, opacity: 0.9 });
  const sprite = new THREE.Sprite(spriteMaterial);
  sprite.scale.set(1.4, 0.7, 1);
  return sprite;
}

const posLabel = createLabelSprite('Position (r)', '#ff4757');
scene.add(posLabel);

const velLabel = createLabelSprite('Velocity (v)', '#00d2d3');
scene.add(velLabel);

const formulaSprite = createLabelSprite('v = dr/dt', '#2d3436');
formulaSprite.scale.set(1.8, 0.9, 1);
formulaSprite.position.set(0, 3.2, 0);
scene.add(formulaSprite);

camera.position.set(5, 4, 6);
camera.lookAt(0, 0.5, 0);

if (typeof OrbitControls !== 'undefined') {
  const controls = new OrbitControls(camera, renderer.domElement);
  controls.enableDamping = true;
  controls.dampingFactor = 0.05;
  controls.maxPolarAngle = Math.PI / 2 - 0.05;
  controls.target.set(0, 0.5, 0);
}

let lastPosition = new THREE.Vector3();
const currentPos = new THREE.Vector3();
const velocity = new THREE.Vector3();

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();

  const scale = 2.2;
  const speed = 0.6;
  const x = scale * Math.cos(speed * t);
  const z = scale * Math.sin(speed * t) * Math.cos(speed * t * 0.5);
  const y = 0.8 + 0.7 * Math.sin(speed * t * 1.5);

  currentPos.set(x, y, z);

  if (t > 0.1) {
    velocity.subVectors(currentPos, lastPosition).multiplyScalar(60);
  }
  lastPosition.copy(currentPos);

  playerGroup.position.copy(currentPos);

  if (velocity.length() > 0.01) {
    const targetPos = currentPos.clone().add(velocity);
    playerGroup.lookAt(targetPos);
    ring.rotation.z = t * 2;
    ring.material.opacity = 0.4 + Math.sin(t * 3) * 0.2;
  }

  const posLength = currentPos.length();
  if (posLength > 0.1) {
    posArrow.position.set(0, 0, 0);
    posArrow.lookAt(currentPos);
    posArrow.rotateX(-Math.PI / 2);
    posArrow.scale.set(1, posLength, 1);

    const midPos = currentPos.clone().multiplyScalar(0.5);
    midPos.y += 0.3;
    posLabel.position.copy(midPos);
  }

  const velMag = velocity.length();
  if (velMag > 0.01) {
    velArrow.position.copy(currentPos);
    const velDir = velocity.clone().normalize();
    const targetPoint = currentPos.clone().add(velDir);
    velArrow.lookAt(targetPoint);
    velArrow.rotateX(-Math.PI / 2);

    const displayLength = Math.min(velMag * 0.25, 2.5);
    velArrow.scale.set(1, displayLength, 1);

    const velMid = currentPos.clone().add(velDir.multiplyScalar(displayLength * 0.5));
    velMid.y += 0.3;
    velLabel.position.copy(velMid);
  }

  trailPoints.push(currentPos.clone());
  if (trailPoints.length > maxTrailPoints) {
    trailPoints.shift();
  }

  if (trailPoints.length > 1) {
    const positions = new Float32Array(trailPoints.length * 3);
    for (let i = 0; i < trailPoints.length; i++) {
      positions[i * 3] = trailPoints[i].x;
      positions[i * 3 + 1] = trailPoints[i].y;
      positions[i * 3 + 2] = trailPoints[i].z;
    }
    trailGeometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));
  }

  rimLight.intensity = 0.35 + Math.sin(t * 1.2) * 0.08;
  keyLight.position.x = 6 + Math.sin(t * 0.3) * 1.5;

  camera.position.y = 4 + Math.sin(t * 0.15) * 0.2;

  renderer.render(scene, camera);
}

animate();

