  const curve = new THREE.CatmullRomCurve3(points);
  const geometry = new THREE.TubeGeometry(curve, 100, 0.06, 12, false);
  const material = new THREE.MeshStandardMaterial({
    color: color,
    emissive: color,
    emissiveIntensity: 0.35,
    roughness: 0.2,
    metalness: 0.8
  });

  const mesh = new THREE.Mesh(geometry, material);
  mesh.position.x = xOffset;
  mesh.castShadow = true;

  const pedestal = new THREE.Mesh(
    new THREE.BoxGeometry(3, 0.15, 2.5),
    new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.15, metalness: 0.05 })
  );
  pedestal.position.set(xOffset, -2.1, 0);
  pedestal.receiveShadow = true;
  pedestal.castShadow = true;

  const label = createTextLabel(name, color);
  label.position.set(xOffset, 2.2, 0);

  const axisGroup = new THREE.Group();
  const axisMat = new THREE.MeshStandardMaterial({ color: 0x94a3b8, roughness: 0.8 });

  const xAxis = new THREE.Mesh(new THREE.CylinderGeometry(0.015, 0.015, 4.2, 8), axisMat);
  xAxis.rotation.z = Math.PI / 2;
  xAxis.position.set(xOffset, -1.8, 0);

  const yAxis = new THREE.Mesh(new THREE.CylinderGeometry(0.015, 0.015, 3.2, 8), axisMat);
  yAxis.position.set(xOffset - 2, -0.2, 0);

  const origin = new THREE.Mesh(new THREE.SphereGeometry(0.06, 16, 16), new THREE.MeshStandardMaterial({ color: 0x475569 }));
  origin.position.set(xOffset - 2, -1.8, 0);

  axisGroup.add(xAxis, yAxis, origin);

  return { mesh, pedestal, label, axisGroup, material };
}

const sigmoid = x => 1 / (1 + Math.exp(-x));
const relu = x => Math.max(0, x);
const tanh = x => Math.tanh(x);

const sigmoidObj = createActivationCurve(sigmoid, 0x3b82f6, -3.5, "Sigmoid");
const reluObj = createActivationCurve(relu, 0xf97316, 0, "ReLU");
const tanhObj = createActivationCurve(tanh, 0x10b981, 3.5, "Tanh");

heroGroup.add(sigmoidObj.mesh, sigmoidObj.pedestal, sigmoidObj.label, sigmoidObj.axisGroup);
heroGroup.add(reluObj.mesh, reluObj.pedestal, reluObj.label, reluObj.axisGroup);
heroGroup.add(tanhObj.mesh, tanhObj.pedestal, tanhObj.label, tanhObj.axisGroup);

const neuronGroup = new THREE.Group();
neuronGroup.position.set(0, 1.2, -3);

const neuronCore = new THREE.Mesh(
  new THREE.IcosahedronGeometry(0.5, 2),
  new THREE.MeshPhysicalMaterial({
    color: 0xffffff,
    metalness: 0.1,
    roughness: 0.1,
    transmission: 0.7,
    thickness: 1.2,
    clearcoat: 1,
    clearcoatRoughness: 0.1
  })
);
neuronCore.castShadow = true;

const nucleus = new THREE.Mesh(
  new THREE.SphereGeometry(0.25, 32, 32),
  new THREE.MeshStandardMaterial({ color: 0x3b82f6, emissive: 0x3b82f6, emissiveIntensity: 0.5 })
);

const inputDendrites = [];
for (let i = 0; i < 5; i++) {
  const angle = (i / 5) * Math.PI + Math.PI;
  const line = new THREE.Mesh(
    new THREE.CylinderGeometry(0.025, 0.025, 1.2, 8),
    new THREE.MeshStandardMaterial({ color: 0x64748b, emissive: 0x3b82f6, emissiveIntensity: 0.1 })
  );
  line.rotation.z = angle - Math.PI / 2;
  line.position.set(Math.cos(angle) * 0.6, Math.sin(angle) * 0.6, 0);
  line.geometry.translate(0, 0.6, 0);
  inputDendrites.push(line);
  neuronGroup.add(line);
}

const outputAxon = new THREE.Mesh(
  new THREE.CylinderGeometry(0.04, 0.06, 1.5, 8),
  new THREE.MeshStandardMaterial({ color: 0x475569, emissive: 0x3b82f6, emissiveIntensity: 0.2 })
);
outputAxon.rotation.z = -Math.PI / 2;
outputAxon.position.set(1.1, 0, 0);
outputAxon.geometry.translate(0, 0.75, 0);
neuronGroup.add(outputAxon);

neuronGroup.add(neuronCore, nucleus);
heroGroup.add(neuronGroup);

const particlesGeometry = new THREE.BufferGeometry();
const particleCount = 300;
const positions = new Float32Array(particleCount * 3);
const velocities = [];

for (let i = 0; i < particleCount; i++) {
  positions[i * 3] = (Math.random() - 0.5) * 16;
  positions[i * 3 + 1] = (Math.random() - 0.5) * 10;
  positions[i * 3 + 2] = (Math.random() - 0.5) * 10;
  velocities.push({
    x: (Math.random() - 0.5) * 0.01,
    y: (Math.random() - 0.5) * 0.01 + 0.005,
    z: (Math.random() - 0.5) * 0.01
  });
}

particlesGeometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));
const particlesMaterial = new THREE.PointsMaterial({
  color: 0x94a3b8,
  size: 0.06,
  transparent: true,
  opacity: 0.5,
  sizeAttenuation: true
});
const particleSystem = new THREE.Points(particlesGeometry, particlesMaterial);
scene.add(particleSystem);

camera.position.set(0, 2.5, 11);
camera.lookAt(0, 0, 0);

if (typeof OrbitControls !== 'undefined') {
  const controls = new OrbitControls(camera, renderer.domElement);
  controls.enableDamping = true;
  controls.dampingFactor = 0.05;
  controls.maxPolarAngle = Math.PI / 2 - 0.1;
  controls.minDistance = 5;
  controls.maxDistance = 20;
}

const activationFunctions = [sigmoidObj, reluObj, tanhObj];
const colors = [0x3b82f6, 0xf97316, 0x10b981];

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();

  heroGroup.rotation.y = Math.sin(t * 0.08) * 0.15;

  const positions = particleSystem.geometry.attributes.position.array;
  for (let i = 0; i < particleCount; i++) {
    positions[i * 3] += velocities[i].x;
    positions[i * 3 + 1] += velocities[i].y;
    positions[i * 3 + 2] += velocities[i].z;

    if (positions[i * 3 + 1] > 5) positions[i * 3 + 1] = -5;
  }
  particleSystem.geometry.attributes.position.needsUpdate = true;

  rimLight.intensity = 0.35 + Math.sin(t * 1.2) * 0.08;

  neuronGroup.rotation.y = t * 0.3;
  neuronCore.rotation.x = t * 0.2;
  neuronCore.rotation.z = t * 0.1;

  const cycleDuration = 10;
  const phase = (t % cycleDuration) / (cycleDuration / 3);
  const activeIndex = Math.min(Math.floor(phase), 2);

  activationFunctions.forEach((obj, idx) => {
    if (idx === activeIndex) {
      const pulse = 0.6 + Math.sin(t * 3) * 0.25;
      obj.material.emissiveIntensity = pulse;
      obj.mesh.scale.setScalar(1 + Math.sin(t * 6) * 0.015);
      obj.label.material.opacity = 1;
    } else {
      obj.material.emissiveIntensity = 0.15;
      obj.mesh.scale.setScalar(1);
      obj.label.material.opacity = 0.4;
    }
  });

  nucleus.material.color.setHex(colors[activeIndex]);
  nucleus.material.emissive.setHex(colors[activeIndex]);
  outputAxon.material.emissive.setHex(colors[activeIndex]);

  inputDendrites.forEach((dendrite, i) => {
    dendrite.material.emissiveIntensity = 0.1 + Math.sin(t * 4 + i) * 0.1;
  });

  renderer.render(scene, camera);
}

animate();
